-- Beauty salon management - database schema (MySQL 8+)
-- Table and column names match the SQL generated by the domain classes in common/src/model.

CREATE DATABASE IF NOT EXISTS `0_seminarski` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `0_seminarski`;

-- Staff who log in to the client application
CREATE TABLE radnik (
    idRadnik       INT AUTO_INCREMENT PRIMARY KEY,
    ime            VARCHAR(50)  NOT NULL,
    prezime        VARCHAR(50)  NOT NULL,
    dnevnica       INT          NOT NULL DEFAULT 0,       -- daily wage
    korisnickoIme  VARCHAR(50)  NOT NULL UNIQUE,          -- username
    sifra          VARCHAR(100) NOT NULL                  -- password
);

-- Service categories (e.g. nails, hair, skin care)
CREATE TABLE kategorija (
    idKategorija     INT AUTO_INCREMENT PRIMARY KEY,
    nazivKategorije  VARCHAR(100) NOT NULL,
    opis             VARCHAR(255)
);

-- Beauticians, each specialised in one category
CREATE TABLE kozmeticar (
    idKozmeticar  INT AUTO_INCREMENT PRIMARY KEY,
    ime           VARCHAR(50) NOT NULL,
    prezime       VARCHAR(50) NOT NULL,
    kategorija    INT NOT NULL,
    CONSTRAINT fk_kozmeticar_kategorija FOREIGN KEY (kategorija) REFERENCES kategorija (idKategorija)
);

-- Salon clients
CREATE TABLE klijent (
    idKlijent     INT AUTO_INCREMENT PRIMARY KEY,
    ime           VARCHAR(50) NOT NULL,
    prezime       VARCHAR(50) NOT NULL,
    brojTelefona  VARCHAR(30)
);

-- Work shifts
CREATE TABLE smena (
    idSmena     INT AUTO_INCREMENT PRIMARY KEY,
    nazivSmena  VARCHAR(50) NOT NULL,
    brojSati    INT NOT NULL,          -- hours per shift
    satnica     INT NOT NULL           -- hourly rate
);

-- Staff-to-shift assignment (radnik-smena)
CREATE TABLE rs (
    datumRS  DATE NOT NULL,
    radnik   INT  NOT NULL,
    smena    INT  NOT NULL,
    PRIMARY KEY (datumRS, radnik, smena),
    CONSTRAINT fk_rs_radnik FOREIGN KEY (radnik) REFERENCES radnik (idRadnik),
    CONSTRAINT fk_rs_smena  FOREIGN KEY (smena)  REFERENCES smena (idSmena)
);

-- Appointment record (header)
CREATE TABLE evidencijatermina (
    idEvidencijaTermina  INT AUTO_INCREMENT PRIMARY KEY,
    datumTermina         DATE NOT NULL,
    ukupnaCena           INT  NOT NULL DEFAULT 0,   -- total price
    radnik               INT  NOT NULL,
    kozmeticar           INT  NOT NULL,
    klijent              INT  NOT NULL,
    CONSTRAINT fk_et_radnik     FOREIGN KEY (radnik)     REFERENCES radnik (idRadnik),
    CONSTRAINT fk_et_kozmeticar FOREIGN KEY (kozmeticar) REFERENCES kozmeticar (idKozmeticar),
    CONSTRAINT fk_et_klijent    FOREIGN KEY (klijent)    REFERENCES klijent (idKlijent)
);

-- Appointment line items (weak entity, identified by appointment + ordinal number)
CREATE TABLE stavkaevidencijetermina (
    evidencijaTermina  INT          NOT NULL,
    rb                 INT          NOT NULL,
    nazivStavkeET      VARCHAR(100) NOT NULL,       -- service name
    trajanjeMinuti     INT          NOT NULL,       -- duration in minutes
    cena               INT          NOT NULL,       -- price
    PRIMARY KEY (evidencijaTermina, rb),
    CONSTRAINT fk_stavka_et FOREIGN KEY (evidencijaTermina) REFERENCES evidencijatermina (idEvidencijaTermina)
);

